"""Conferencia independente do fechamento Tarvo set/2026 (so biblioteca padrao).

Uso: python3 -I calc.py <pasta_dados> <xlsx_anexo_ponte>
"""
import csv, sys, zipfile, re, json, collections, datetime
import xml.etree.ElementTree as ET
from decimal import Decimal as Dec, ROUND_HALF_UP

DADOS = sys.argv[1].rstrip('/') + '/'
ANEXO = sys.argv[2]
C = Dec('0.01')


def r2(x):
    # F10: meio centavo para cima, simetrico no negativo (-0,005 -> -0,01)
    return x.quantize(C, rounding=ROUND_HALF_UP)


def br(s):
    s = (s or '').strip()
    if s == '':
        return None
    return Dec(s.replace('.', '').replace(',', '.')) if ',' in s else Dec(s)


def dt(s):
    return datetime.datetime.strptime(s, '%d/%m/%Y').date()


# ---------- xlsx (zipfile + xml) ----------
NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}


def read_xlsx(path):
    z = zipfile.ZipFile(path)
    ss = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            ss.append(''.join(t.text or '' for t in si.iter('{%s}t' % NS['m'])))
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {r.get('Id'): r.get('Target') for r in rels}
    out = {}
    for s in wb.find('m:sheets', NS):
        target = relmap[s.get('{%s}id' % NS['r'])]
        p = 'xl/' + target if not target.startswith('/') else target[1:]
        sh = ET.fromstring(z.read(p))
        rows = {}
        for row in sh.iter('{%s}row' % NS['m']):
            d = {}
            for c in row.findall('m:c', NS):
                t = c.get('t'); v = c.find('m:v', NS); isel = c.find('m:is', NS)
                if t == 's' and v is not None:
                    val = ss[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{%s}t' % NS['m']))
                else:
                    val = v.text if v is not None else ''
                col = re.match(r'[A-Z]+', c.get('r')).group(0)
                d[col] = val
            rows[int(row.get('r'))] = d
        out[s.get('name')] = rows
    return out


def pct(v):
    v = (v or '').strip()
    if v == '' or v.lower() == 'padrão' or v.lower() == 'padrao':
        return None
    if v.endswith('%'):
        return Dec(v[:-1].replace(',', '.')) / 100
    return Dec(v).quantize(Dec('0.000001'))


def cnpj14(v):
    return re.sub(r'\D', '', v or '').zfill(14)


# ---------- planilha de taxas ----------
tab = read_xlsx(DADOS + '02_tabela_taxas_contratadas.xlsx')['Taxas vigentes']
contratos = []  # cada linha da aba vigente
for n, d in tab.items():
    if n < 6 or 'A' not in d or not d['A'] or d['A'].startswith('*'):
        continue
    contratos.append(dict(linha=n, lojista=d['A'], cnpj=cnpj14(d.get('B')), ec=(d.get('C') or '').strip(),
                          deb=pct(d.get('D')), avista=pct(d.get('E')), p26=pct(d.get('F')), p712=pct(d.get('G')),
                          pix=pct(d.get('H')), antec=pct(d.get('I')), spread_raw=d.get('J', ''),
                          vig=d.get('K', ''), obs=d.get('L', '')))
por_linha = {c['linha']: c for c in contratos}
# F6: ECs sem EC na planilha
EC_EXTRA = {'1043300981': 28, '1043396662': 8, '1038867654': 9}
EC_SEM_CONTRATO = {'1076801732'}  # F7 Atlas
BRIDGE_EC = '1075624862'


def linha_contrato(ec, data_ref):
    if ec == BRIDGE_EC:
        return por_linha[6] if data_ref <= datetime.date(2026, 9, 14) else por_linha[7]
    if ec in EC_EXTRA:
        return por_linha[EC_EXTRA[ec]]
    for c in contratos:
        if c['ec'] == ec:
            return c
    return None


def faixa(c, modalidade, parcelas, tipo):
    if tipo in ('ANTECIPACAO', 'REVERSAO ANTECIPACAO'):
        return c['antec'], 'antecipacao'
    if modalidade == 'DEBITO':
        return c['deb'], 'debito'
    if modalidade == 'PIX':
        return c['pix'], 'pix'
    if modalidade == 'CREDITO A VISTA':
        return c['avista'], 'credito_avista'
    if modalidade == 'CREDITO PARCELADO':
        p = int(parcelas)
        if 2 <= p <= 6:
            return c['p26'], 'credito_2a6'
        if 7 <= p <= 12:
            return c['p712'], 'credito_7a12'
        raise ValueError('parcelas fora de 2..12: %s' % parcelas)
    raise ValueError('modalidade? %s' % modalidade)


CASA_EC = '1018325654'
ISENCAO_INI, ISENCAO_FIM = datetime.date(2026, 9, 1), datetime.date(2026, 12, 31)

# ---------- Orbe: 01 + 06 ----------
linhas = []
for arq in ['01_orbe_relatorio_comissoes_set2026.csv', '06_orbe_ajustes_tardios_set2026.csv']:
    with open(DADOS + arq, encoding='utf-8', newline='') as fh:
        for i, r in enumerate(csv.DictReader(fh, delimiter=';')):
            r['_arq'] = arq
            r['_linha_fisica'] = i + 2
            linhas.append(r)
por_id = {r['id_transacao']: r for r in linhas}

res = []
for r in linhas:
    ec = r['cod_estabelecimento']
    tipo = r['tipo_lancamento']
    bruto = br(r['valor_bruto'])
    aplic = br(r['taxa_aplicada_pct']) / 100
    dmov = dt(r['data_movimento'])
    # data que define a taxa: venda/antecipacao = data do movimento; estorno = venda original (F3/F39/F66);
    # reversao = data da antecipacao que ela reverte (F4)
    if tipo in ('ESTORNO', 'REVERSAO ANTECIPACAO'):
        dref = dt(r['data_venda_original'])
    else:
        dref = dmov
    o = dict(id=r['id_transacao'], arq=r['_arq'], lin=r['_linha_fisica'], ec=ec, nome=r['nome_estabelecimento'],
             tipo=tipo, mod=r['modalidade'], parc=r['qtd_parcelas'], bruto=bruto, aplic=aplic, dref=dref,
             valor_taxa=br(r['valor_taxa']))
    if ec in EC_SEM_CONTRATO:
        o.update(sem_contrato=True, lojista='Atlas Idiomas (sem contrato)', cnpj='', contr=None, efet=None,
                 comissao=Dec('0'), faixa='')
        res.append(o); continue
    c = linha_contrato(ec, dref)
    contr, fx = faixa(c, r['modalidade'], r['qtd_parcelas'], tipo)
    efet = contr
    isento = False
    if ec == CASA_EC and ISENCAO_INI <= dref <= ISENCAO_FIM:
        efet = Dec('0'); isento = True  # F9/F68/F75/F86
    o.update(sem_contrato=False, lojista=c['lojista'], cnpj=c['cnpj'], linha_planilha=c['linha'], contr=contr,
             efet=efet, faixa=fx, isento=isento, comissao=r2(bruto * efet))
    res.append(o)

# agregados checkout
com = collections.OrderedDict()
for o in res:
    if o['sem_contrato']:
        continue
    k = (o['cnpj'], o['lojista'] if o['ec'] != BRIDGE_EC else 'Bridge Idiomas')
    com.setdefault(k, Dec('0'))
    com[k] += o['comissao']
tot_checkout = sum(com.values())
atlas = [o for o in res if o['sem_contrato']]

# divergencias de contrato (F2, F11, F38, F63, F66): taxa aplicada != contratada (a da planilha, sem isencao)
div = []
for o in res:
    if o['sem_contrato']:
        continue
    if o['aplic'] != o['contr']:
        d = r2(o['bruto'] * (o['aplic'] - o['contr']))
        div.append(dict(o, dif=d))
tot_div = sum(x['dif'] for x in div)
# isencao Casa (F37/F57/F70): cobrado pela Orbe sobre linhas isentas; devolucao = valor_taxa (F72/F90)
casa_isentas = [o for o in res if o.get('isento')]
casa_bruto_x_taxa = sum(r2(o['bruto'] * o['aplic']) for o in casa_isentas)
casa_valor_taxa = sum(o['valor_taxa'] for o in casa_isentas)

# ---------- Ponte ----------
pt = read_xlsx(ANEXO)['Operações']
hdr = pt[5]
ops = []
for n in sorted(pt):
    if n <= 5:
        continue
    d = pt[n]
    a = (d.get('A') or '').strip()
    if not a.startswith('PC-'):
        continue
    ops.append(dict(linha=n, op=a, dcontr=datetime.date(1899, 12, 30) + datetime.timedelta(days=int(float(d['B']))),
                    dliq=datetime.date(1899, 12, 30) + datetime.timedelta(days=int(float(d['C']))),
                    cnpj=cnpj14(d.get('D')), cliente=d.get('E', ''), moeda=d.get('F', ''),
                    vme=Dec(d['G']), tx=Dec(d['H']), ptax=Dec(d['I']), vbrl=r2(Dec(d['J'])),
                    spread=r2(Dec(d['K'])), spct=Dec(d['L']), status=d.get('O', ''), obs=d.get('P', '')))
cont_op = collections.Counter(x['op'] for x in ops)
dups = {k: v for k, v in cont_op.items() if v > 1}
cnpj_planilha = {c['cnpj']: c for c in contratos}


def spread_contr(cnpj):
    c = cnpj_planilha.get(cnpj)
    if c is None:
        return None
    v = pct(c['spread_raw'])
    return v if v is not None else Dec('0.015')  # F16


vistos = set(); rem = []
for x in ops:
    motivo = None
    if x['op'] in vistos:
        motivo = 'duplicada (F18/F34)'
    vistos.add(x['op'])
    if motivo is None and x['spread'] < 0:
        motivo = 'spread negativo (F17)'
    if motivo is None and not (datetime.date(2026, 9, 1) <= x['dcontr'] <= datetime.date(2026, 9, 30)):
        motivo = 'contratacao fora de setembro (F20)'
    x['excluida'] = motivo
    x['part'] = Dec('0') if motivo else r2(x['spread'] * Dec('0.5'))
    x['contr_pct'] = spread_contr(x['cnpj'])
    rem.append(x)
tot_rem = sum(x['part'] for x in rem)
rem_loj = collections.OrderedDict()
for x in rem:
    if x['excluida']:
        continue
    c = cnpj_planilha.get(x['cnpj'])
    k = (x['cnpj'], c['lojista'] if c else 'FORA DA PLANILHA ' + x['cliente'])
    rem_loj[k] = rem_loj.get(k, Dec('0')) + x['part']
# divergencia de remessa (F14/F15/F63): spread % aplicado acima do contratado; valor cheio
rdiv = []
for x in rem:
    if x['excluida'] or x['contr_pct'] is None:
        continue
    if abs(x['spct'] - x['contr_pct']) > Dec('0.0002'):
        base = x['vme'] * x['ptax']
        v_pct = r2(base * (x['spct'] - x['contr_pct']))           # pelo spread %
        v_rs = r2(x['spread'] - r2(base * x['contr_pct']))       # pelo Spread R$ realizado
        rdiv.append(dict(x, v_pct=v_pct, v_rs=v_rs))

# ---------- Extratos ----------
aur = open(DADOS + '05a_extrato_banco_aurora_cc4471_set2026.csv', encoding='utf-8').read().split('\n')
aur_lanc = []
for i, l in enumerate(aur, start=1):
    p = l.split(';')
    if len(p) >= 4 and re.match(r'\d{2}/\d{2}/\d{4}$', p[0]) and p[1] != 'SALDO ANTERIOR' and p[3].strip():
        aur_lanc.append((i, p[0], p[1], br(p[3])))
ofx = open(DADOS + '05b_extrato_banco_meridiano_cc90233_set2026.ofx', encoding='cp1252').read()
mer = re.findall(r'<STMTTRN>(.*?)</STMTTRN>', ofx, re.S)
mer_lanc = []
for b in mer:
    g = lambda t: (re.search('<%s>([^\r\n<]*)' % t, b) or [None, ''])[1].strip()
    mer_lanc.append((g('FITID'), g('DTPOSTED')[:8], g('MEMO'), Dec(g('TRNAMT'))))

out = dict(
    n_orbe_01=sum(1 for o in res if o['arq'].startswith('01')),
    n_orbe_06=sum(1 for o in res if o['arq'].startswith('06')),
    tot_checkout=str(tot_checkout),
    com=[(k[0], k[1], str(v)) for k, v in com.items()],
    atlas_n=len(atlas), atlas_bruto=str(sum(o['bruto'] for o in atlas)),
    atlas_valor_taxa=str(sum(o['valor_taxa'] for o in atlas)),
    n_div=len(div), tot_div=str(tot_div),
    casa_n=len(casa_isentas), casa_bruto_x_taxa=str(casa_bruto_x_taxa), casa_valor_taxa=str(casa_valor_taxa),
    n_ops=len(ops), dups=dups, tot_rem=str(tot_rem),
    rem_loj=[(k[0], k[1], str(v)) for k, v in rem_loj.items()],
    n_aur=len(aur_lanc), aur_soma=str(sum(x[3] for x in aur_lanc)),
    n_mer=len(mer_lanc), mer_soma=str(sum(x[3] for x in mer_lanc)),
)
if __name__ == '__main__':
    import pickle
    pickle.dump(dict(res=res, div=div, ops=ops, rem=rem, rdiv=rdiv, com=com, rem_loj=rem_loj,
                     aur=aur_lanc, mer=mer_lanc, casa=casa_isentas, atlas=atlas, contratos=contratos),
                open(sys.argv[3] if len(sys.argv) > 3 else 'estado.pkl', 'wb'))
    print(json.dumps(out, indent=1, ensure_ascii=False, default=str))

