"""Conferencia independente do fechamento Tarvo set/2026 (so biblioteca padrao).

Uso: python3 -I calc.py <pasta_dados> <xlsx_anexo_ponte>
"""
import csv, sys, zipfile, re, json, collections, datetime
import xml.etree.ElementTree as ET
from decimal import Decimal as Dec, ROUND_HALF_UP

DADOS = sys.argv[1].rstrip('/') + '/'
ANEXO = sys.argv[2]
C = Dec('0.01')


def r2(x):
    # F10: meio centavo para cima, simetrico no negativo (-0,005 -> -0,01)
    return x.quantize(C, rounding=ROUND_HALF_UP)


def br(s):
    s = (s or '').strip()
    if s == '':
        return None
    return Dec(s.replace('.', '').replace(',', '.')) if ',' in s else Dec(s)


def dt(s):
    return datetime.datetime.strptime(s, '%d/%m/%Y').date()


# ---------- xlsx (zipfile + xml) ----------
NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}


def read_xlsx(path):
    z = zipfile.ZipFile(path)
    ss = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            ss.append(''.join(t.text or '' for t in si.iter('{%s}t' % NS['m'])))
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {r.get('Id'): r.get('Target') for r in rels}
    out = {}
    for s in wb.find('m:sheets', NS):
        target = relmap[s.get('{%s}id' % NS['r'])]
        p = 'xl/' + target if not target.startswith('/') else target[1:]
        sh = ET.fromstring(z.read(p))
        rows = {}
        for row in sh.iter('{%s}row' % NS['m']):
            d = {}
            for c in row.findall('m:c', NS):
                t = c.get('t'); v = c.find('m:v', NS); isel = c.find('m:is', NS)
                if t == 's' and v is not None:
                    val = ss[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{%s}t' % NS['m']))
                else:
                    val = v.text if v is not None else ''
                col = re.match(r'[A-Z]+', c.get('r')).group(0)
                d[col] = val
            rows[int(row.get('r'))] = d
        out[s.get('name')] = rows
    return out


def pct(v):
    v = (v or '').strip()
    if v == '' or v.lower() == 'padrão' or v.lower() == 'padrao':
        return None
    if v.endswith('%'):
        return Dec(v[:-1].replace(',', '.')) / 100
    return Dec(v).quantize(Dec('0.000001'))


def cnpj14(v):
    return re.sub(r'\D', '', v or '').zfill(14)


# ---------- planilha de taxas ----------
tab = read_xlsx(DADOS + '02_tabela_taxas_contratadas.xlsx')['Taxas vigentes']
contratos = []  # cada linha da aba vigente
for n, d in tab.items():
    if n < 6 or 'A' not in d or not d['A'] or d['A'].startswith('*'):
        continue
    contratos.append(dict(linha=n, lojista=d['A'], cnpj=cnpj14(d.get('B')), ec=(d.get('C') or '').strip(),
                          deb=pct(d.get('D')), avista=pct(d.get('E')), p26=pct(d.get('F')), p712=pct(d.get('G')),
                          pix=pct(d.get('H')), antec=pct(d.get('I')), spread_raw=d.get('J', ''),
                          vig=d.get('K', ''), obs=d.get('L', '')))
por_linha = {c['linha']: c for c in contratos}
# F6: ECs sem EC na planilha
EC_EXTRA = {'1043300981': 28, '1043396662': 8, '1038867654': 9}
EC_SEM_CONTRATO = {'1076801732'}  # F7 Atlas
BRIDGE_EC = '1075624862'


def linha_contrato(ec, data_ref):
    if ec == BRIDGE_EC:
        return por_linha[6] if data_ref <= datetime.date(2026, 9, 14) else por_linha[7]
    if ec in EC_EXTRA:
        return por_linha[EC_EXTRA[ec]]
    for c in contratos:
        if c['ec'] == ec:
            return c
    return None


def faixa(c, modalidade, parcelas, tipo):
    if tipo in ('ANTECIPACAO', 'REVERSAO ANTECIPACAO'):
        return c['antec'], 'antecipacao'
    if modalidade == 'DEBITO':
        return c['deb'], 'debito'
    if modalidade == 'PIX':
        return c['pix'], 'pix'
    if modalidade == 'CREDITO A VISTA':
        return c['avista'], 'credito_avista'
    if modalidade == 'CREDITO PARCELADO':
        p = int(parcelas)
        if 2 <= p <= 6:
            return c['p26'], 'credito_2a6'
        if 7 <= p <= 12:
            return c['p712'], 'credito_7a12'
        raise ValueError('parcelas fora de 2..12: %s' % parcelas)
    raise ValueError('modalidade? %s' % modalidade)


CASA_EC = '1018325654'
ISENCAO_INI, ISENCAO_FIM = datetime.date(2026, 9, 1), datetime.date(2026, 12, 31)

# ---------- Orbe: 01 + 06 ----------
linhas = []
for arq in ['01_orbe_relatorio_comissoes_set2026.csv', '06_orbe_ajustes_tardios_set2026.csv']:
    with open(DADOS + arq, encoding='utf-8', newline='') as fh:
        for i, r in enumerate(csv.DictReader(fh, delimiter=';')):
            r['_arq'] = arq
            r['_linha_fisica'] = i + 2
            linhas.append(r)
por_id = {r['id_transacao']: r for r in linhas}

res = []
for r in linhas:
    ec = r['cod_estabelecimento']
    tipo = r['tipo_lancamento']
    bruto = br(r['valor_bruto'])
