"""Conferencia independente do fechamento Tarvo set/2026 (so biblioteca padrao).

Uso: python3 -I calc.py <pasta_dados> <xlsx_anexo_ponte>
"""
import csv, sys, zipfile, re, json, collections, datetime
import xml.etree.ElementTree as ET
from decimal import Decimal as Dec, ROUND_HALF_UP

DADOS = sys.argv[1].rstrip('/') + '/'
ANEXO = sys.argv[2]
C = Dec('0.01')


def r2(x):
    # F10: meio centavo para cima, simetrico no negativo (-0,005 -> -0,01)
    return x.quantize(C, rounding=ROUND_HALF_UP)


def br(s):
    s = (s or '').strip()
    if s == '':
        return None
    return Dec(s.replace('.', '').replace(',', '.')) if ',' in s else Dec(s)


def dt(s):
    return datetime.datetime.strptime(s, '%d/%m/%Y').date()


# ---------- xlsx (zipfile + xml) ----------
NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}


def read_xlsx(path):
    z = zipfile.ZipFile(path)
    ss = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            ss.append(''.join(t.text or '' for t in si.iter('{%s}t' % NS['m'])))
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {r.get('Id'): r.get('Target') for r in rels}
    out = {}
    for s in wb.find('m:sheets', NS):
        target = relmap[s.get('{%s}id' % NS['r'])]
        p = 'xl/' + target if not target.startswith('/') else target[1:]
        sh = ET.fromstring(z.read(p))
        rows = {}
        for row in sh.iter('{%s}row' % NS['m']):
            d = {}
            for c in row.findall('m:c', NS):
                t = c.get('t'); v = c.find('m:v', NS); isel = c.find('m:is', NS)
                if t == 's' and v is not None:
                    val = ss[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{%s}t' % NS['m']))
                else:
                    val = v.text if v is not None else ''
                col = re.match(r'[A-Z]+', c.get('r')).group(0)
                d[col] = val
            rows[int(row.get('r'))] = d
        out[s.get('name')] = rows
    return out


def pct(v):
    v = (v or '').strip()
    if v == '' or v.lower() == 'padrão' or v.lower() == 'padrao':
        return None
    if v.endswith('%'):
        return Dec(v[:-1].replace(',', '.')) / 100
    return Dec(v).quantize(Dec('0.000001'))


def cnpj14(v):
    return re.sub(r'\D', '', v or '').zfill(14)


# ---------- planilha de taxas ----------
tab = read_xlsx(DADOS + '02_tabela_taxas_contratadas.xlsx')['Taxas vigentes']
contratos = []  # cada linha da aba vigente
for n, d in tab.items():
