EC_SEM_CONTRATO = {'1076801732'}  # F7 Atlas
BRIDGE_EC = '1075624862'


def linha_contrato(ec, data_ref):
    if ec == BRIDGE_EC:
        return por_linha[6] if data_ref <= datetime.date(2026, 9, 14) else por_linha[7]
    if ec in EC_EXTRA:
        return por_linha[EC_EXTRA[ec]]
    for c in contratos:
        if c['ec'] == ec:
            return c
    return None


def faixa(c, modalidade, parcelas, tipo):
    if tipo in ('ANTECIPACAO', 'REVERSAO ANTECIPACAO'):
        return c['antec'], 'antecipacao'
    if modalidade == 'DEBITO':
        return c['deb'], 'debito'
    if modalidade == 'PIX':
        return c['pix'], 'pix'
    if modalidade == 'CREDITO A VISTA':
