    com.setdefault(k, Dec('0'))
    com[k] += o['comissao']
tot_checkout = sum(com.values())
atlas = [o for o in res if o['sem_contrato']]

# divergencias de contrato (F2, F11, F38, F63, F66): taxa aplicada != contratada (a da planilha, sem isencao)
