"""Fase 2: compara os CSVs de saida/ com os totais independentes (estado.pkl de calc.py).

Uso: python3 -I compare.py <pasta saida> <estado.pkl>
So le arquivos *.csv da pasta saida indicada.
"""
import csv, sys, os, re, pickle, collections
from decimal import Decimal as Dec, InvalidOperation

SAIDA = sys.argv[1].rstrip('/') + '/'
st = pickle.load(open(sys.argv[2], 'rb'))


def load(nome):
    p = SAIDA + nome
    if not os.path.exists(p):
        return None
    with open(p, encoding='utf-8-sig', newline='') as fh:
        rd = csv.reader(fh, delimiter=';')
        rows = list(rd)
    if not rows:
        return []
    hdr = [h.strip().lower() for h in rows[0]]
    out = []
    for i, r in enumerate(rows[1:], start=2):
        if not any(c.strip() for c in r):
            continue
        d = {hdr[j]: (r[j].strip() if j < len(r) else '') for j in range(len(hdr))}
        d['_linha'] = i
        out.append(d)
    return out


def dec(s):
    s = (s or '').strip()
    if s == '':
        return None
    try:
        return Dec(s)
    except InvalidOperation:
        try:
            return Dec(s.replace('.', '').replace(',', '.'))
        except InvalidOperation:
            return None


def cnpj14(v):
    return re.sub(r'\D', '', v or '').zfill(14)


print('# arquivos em saida/:', sorted(os.listdir(SAIDA)))

# ---------- comissoes ----------
com = load('comissoes_por_lojista.csv')
meu_ck = {k[0]: (k[1], v) for k, v in st['com'].items()}
meu_rm = {k[0]: (k[1], v) for k, v in st['rem_loj'].items()}
if com is not None:
    print('\n## comissoes_por_lojista.csv: %d linhas; colunas %s' % (len(com), list(com[0].keys()) if com else []))
    tot = collections.defaultdict(Dec)
    sol = collections.defaultdict(dict)
    for r in com:
        ln = (r.get('linha_negocio') or '').upper()
        v = dec(r.get('comissao_brl')) or Dec(0)
        tot[ln] += v
        sol[ln][cnpj14(r.get('cnpj'))] = (r.get('lojista'), v, r.get('id_saida'), r)
    print('totais solucao:', {k: str(v) for k, v in tot.items()})
    print('meus: CHECKOUT %s REMESSA %s' % (sum(v for _, v in meu_ck.values()), sum(v for _, v in meu_rm.values())))
    for ln, meu in (('CHECKOUT', meu_ck), ('REMESSA', meu_rm)):
        s = sol.get(ln, {})
        for c in sorted(set(s) | set(meu)):
            a = meu.get(c, (None, None)); b = s.get(c, (None, None, None, None))
            if a[1] != b[1]:
                print('  DIF %s %s %s meu=%s solucao=%s id_saida=%s extra=%s' % (
                    ln, c, a[0] or b[0], a[1], b[1], b[2],
                    {k: v for k, v in (b[3] or {}).items() if k not in ('cnpj', 'lojista', 'linha_negocio', 'comissao_brl', 'id_saida', '_linha')}))

# ---------- divergencias ----------
dv = load('divergencias_taxa.csv')
if dv is not None:
    print('\n## divergencias_taxa.csv: %d linhas; colunas %s' % (len(dv), list(dv[0].keys()) if dv else []))
    tot = collections.defaultdict(Dec); cnt = collections.Counter()
    sol = {}
    extra_cols = [k for k in (dv[0].keys() if dv else []) if k not in (
        'id_saida', 'cnpj', 'linha_negocio', 'ref_origem', 'taxa_contratada_pct', 'taxa_aplicada_pct', 'diferenca_brl', '_linha')]
    por_causa = collections.defaultdict(lambda: [0, Dec(0)])
    for r in dv:
        ln = (r.get('linha_negocio') or '').upper()
        v = dec(r.get('diferenca_brl')) or Dec(0)
        tot[ln] += v; cnt[ln] += 1
        sol[(ln, r.get('ref_origem'))] = (v, r)
        key = (ln,) + tuple(r.get(k, '') for k in extra_cols[:2])
        por_causa[key][0] += 1; por_causa[key][1] += v
    print('totais solucao:', {k: (cnt[k], str(v)) for k, v in tot.items()})
    print('por linha_negocio + colunas extras %s:' % extra_cols[:2])
    for k, v in sorted(por_causa.items()):
        print('   ', k, v[0], v[1])
    meu = {('CHECKOUT', d['id']): d['dif'] for d in st['div']}
    for x in st['rdiv']:
        meu[('REMESSA', x['op'])] = x['v_rs']
    print('meus: CHECKOUT %d %s | REMESSA %d %s (pct %s)' % (
        len(st['div']), sum(d['dif'] for d in st['div']), len(st['rdiv']), sum(x['v_rs'] for x in st['rdiv']),
        sum(x['v_pct'] for x in st['rdiv'])))
    so_sol = [k for k in sol if k not in meu]
    so_meu = [k for k in meu if k not in sol]
    difv = [k for k in sol if k in meu and sol[k][0] != meu[k]]
    print('so na solucao: %d, soma %s' % (len(so_sol), sum(sol[k][0] for k in so_sol)))
    for k in so_sol[:200]:
        r = sol[k][1]
        print('   ', k, sol[k][0], r.get('cnpj'), r.get('taxa_contratada_pct'), r.get('taxa_aplicada_pct'),
              {c: r.get(c) for c in extra_cols})
    print('so no meu: %d, soma %s' % (len(so_meu), sum(meu[k] for k in so_meu)))
    for k in so_meu[:200]:
        print('   ', k, meu[k])
    print('valor diferente: %d' % len(difv))
    for k in difv[:200]:
        print('   ', k, 'meu', meu[k], 'sol', sol[k][0], sol[k][1].get('taxa_contratada_pct'), sol[k][1].get('taxa_aplicada_pct'))

# ---------- notas ----------
nt = load('notas_a_emitir.csv')
if nt is not None:
    print('\n## notas_a_emitir.csv: %d linhas; colunas %s' % (len(nt), list(nt[0].keys()) if nt else []))
    tot = collections.defaultdict(Dec); cnt = collections.Counter()
    for r in nt:
        ln = (r.get('linha_negocio') or '').upper()
        v = dec(r.get('valor_brl')) or Dec(0)
        tot[ln] += v; cnt[ln] += 1
