lc = load('lancamentos_classificados.csv')
if lc is not None:
    print('\n## lancamentos_classificados.csv: %d linhas; colunas %s' % (len(lc), list(lc[0].keys()) if lc else []))
    cnt = collections.Counter((r.get('banco') or '').upper() for r in lc)
    print('por banco (solucao):', dict(cnt))
    print('meus: AURORA %d MERIDIANO %d' % (len(st['aur']), len(st['mer'])))
    ref_a = {('L%d' % x[0]): x for x in st['aur']}
    ref_m = {x[0]: x for x in st['mer']}
    sa = collections.Counter(r.get('ref_origem') for r in lc if (r.get('banco') or '').upper() == 'AURORA')
    sm = collections.Counter(r.get('ref_origem') for r in lc if (r.get('banco') or '').upper() == 'MERIDIANO')
    print('AURORA so na solucao:', sorted(set(sa) - set(ref_a)), 'so no meu:', sorted(set(ref_a) - set(sa)),
          'repetidos:', [k for k, v in sa.items() if v > 1])
    print('MERIDIANO so na solucao:', sorted(set(sm) - set(ref_m)), 'so no meu:', sorted(set(ref_m) - set(sm)),
          'repetidos:', [k for k, v in sm.items() if v > 1])
    # valor e data
    nval = 0
    for r in lc:
        b = (r.get('banco') or '').upper(); ref = r.get('ref_origem'); v = dec(r.get('valor'))
        x = ref_a.get(ref) if b == 'AURORA' else ref_m.get(ref)
        if x is not None and v is not None and v != x[3]:
            nval += 1
            if nval <= 20:
                print('  VALOR DIF', b, ref, 'extrato', x[3], 'sol', v)
    print('valores diferentes do extrato:', nval)
    print('soma valor solucao por banco:', {b: str(sum((dec(r.get('valor')) or Dec(0)) for r in lc if (r.get('banco') or '').upper() == b)) for b in cnt})
    print('metodo:', collections.Counter(r.get('metodo') for r in lc))

# ---------- pendencias ----------
pd = load('pendencias.csv')
if pd is not None:
    print('\n## pendencias.csv: %d linhas' % len(pd))
    for r in pd:
        print('   ', r.get('id_saida'), '|', r.get('tipo'), '|', (r.get('ref_origem') or '')[:60], '|', r.get('valor_brl'), '|', (r.get('quem_decide') or '')[:30])

# ---------- rastro ----------
ra = load('rastro.csv')
if ra is not None:
    print('\n## rastro.csv: %d linhas; colunas %s' % (len(ra), list(ra[0].keys()) if ra else []))
    soma = collections.defaultdict(Dec); n = collections.Counter()
    for r in ra:
        soma[r.get('id_saida')] += dec(r.get('valor')) or Dec(0); n[r.get('id_saida')] += 1
    reportado = {}
    for nome, col in (('comissoes_por_lojista.csv', 'comissao_brl'), ('notas_a_emitir.csv', 'valor_brl'),
                      ('divergencias_taxa.csv', 'diferenca_brl'), ('pendencias.csv', 'valor_brl'),
                      ('lancamentos_classificados.csv', 'valor')):
        for r in (load(nome) or []):
            if r.get('id_saida'):
                reportado[r['id_saida']] = (nome, dec(r.get(col)))
    falta = [k for k in reportado if k not in soma]
    bate = 0; nao = []
    for k, (nome, v) in reportado.items():
        if k in soma:
            if v is not None and soma[k] == v:
                bate += 1
            else:
                nao.append((k, nome, v, soma[k], n[k]))
    print('id_saida reportados: %d; com rastro que bate: %d; sem rastro: %d; nao bate: %d' % (
        len(reportado), bate, len(falta), len(nao)))
    from collections import Counter as Ct
    print('sem rastro por arquivo:', Ct(reportado[k][0] for k in falta))
    for x in nao[:40]:
        print('   NAO BATE', x)
    st_ids = set(soma) - set(reportado)
    print('id_saida no rastro sem saida correspondente:', len(st_ids), sorted(st_ids)[:10])

