"""
import csv, sys, pickle, collections
from decimal import Decimal as Dec

SAIDA = sys.argv[1].rstrip('/') + '/'
st = pickle.load(open(sys.argv[2], 'rb'))
ids = sys.argv[3]
cnpj = sys.argv[4]
ln = sys.argv[5] if len(sys.argv) > 5 else 'CHECKOUT'

with open(SAIDA + 'rastro.csv', encoding='utf-8-sig', newline='') as fh:
    rows = list(csv.reader(fh, delimiter=';'))
hdr = [h.strip().lower() for h in rows[0]]
ra = [dict(zip(hdr, [c.strip() for c in r])) for r in rows[1:] if r]
sol = collections.defaultdict(Dec)
