    mv = {k: x['part'] for k, x in meu.items()}

print('id_saida', ids, 'linhas no rastro', len(sol), 'soma', sum(sol.values()), '| meu', len(mv), 'soma', sum(mv.values()))
for k in sorted(set(sol) | set(mv)):
    a, b = mv.get(k), sol.get(k)
    if a != b:
        o = meu.get(k)
        info = ''
        if o is not None and ln == 'CHECKOUT':
            info = '%s %s %s %s bruto=%s contr=%s aplic=%s efet=%s dref=%s arq=%s L%s' % (
                o['tipo'], o['mod'], o['parc'], o['nome'], o['bruto'], o['contr'], o['aplic'], o['efet'], o['dref'],
                o['arq'][:2], o['lin'])
        elif o is not None:
            info = 'linha %s %s spread=%s' % (o['linha'], o['cliente'], o['spread'])
        print('  %s meu=%s sol=%s arq_sol=%s %s' % (k, a, b, arq.get(k), info))

