ec2row = {g['C%d' % n].strip(): n for n in range(6, 31) if g.get('C%d' % n) and n in tab}
ec2row.update({'1043300981': 28, '1043396662': 8, '1038867654': 9})


def cents(s):
    neg = s.startswith('-')
    a, b = s.lstrip('-').replace('.', '').split(',')
    v = int(a) * 100 + int((b + '00')[:2])
    return -v if neg else v


def rnd(num, den):
    # arredonda num/den para inteiro, meio para cima simetrico
    q, r = divmod(abs(num), den)
    if 2 * r >= den:
        q += 1
    return q if num >= 0 else -q


