            tx = taxas[0]
        elif r['modalidade'] == 'PIX':
            tx = taxas[4]
        elif r['modalidade'] == 'CREDITO A VISTA':
            tx = taxas[1]
        else:
            tx = taxas[2] if int(r['qtd_parcelas']) <= 6 else taxas[3]
        if ec == '1018325654' and 20260901 <= ref <= 20261231:
            tx = 0
        c = rnd(cents(r['valor_bruto']) * tx, 1000000)
        tot[ec] = tot.get(ec, 0) + c
print('CHECKOUT por EC (centavos):')
for ec in sorted(tot):
    print(' ', ec, tot[ec] / 100)
print('TOTAL CHECKOUT', sum(tot.values()) / 100, 'notas>0:', sum(v for v in tot.values() if v > 0) / 100)

p = cells(sys.argv[2], 1)
seen = set(); part = 0; n = 0
for i in range(6, 400):
    op = p.get('A%d' % i, '')
    if not op.startswith('PC-'):
        continue
    sp = round(float(p['K%d' % i]) * 100)
    if op in seen or sp < 0:
        seen.add(op); continue
    seen.add(op)
    part += rnd(sp, 2); n += 1
print('PONTE ops', n, 'participacao', part / 100)

